74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    /**
77	     * Dedicated audit logger. A successful owner create emits a single line here carrying the new
78	     * owner's id, customer code, registration date and membership level, so the create side-effect
79	     * can be audited independently of the application log.
80	     */
81	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
82	
83	    private final ClinicService clinicService;
84	
85	    private final OwnerMapper ownerMapper;
86	
87	    private final PetMapper petMapper;
88	
89	    private final VisitMapper visitMapper;
90	
91	    /**
92	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
93	     * and a domain containing at least one dot, with no whitespace in any segment.
94	     */
95	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
96	
97	    /**
98	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email address
99	     * is on this blocklist (compared case-insensitively on the domain, the part after the final
100	     * {@code '@'}) is rejected with a 400 Bad Request.
101	     */
102	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
103	        "mailinator.com",
104	        "tempmail.com",
105	        "guerrillamail.com");
106	
107	    /**
108	     * Required national-number length per E.164 country code. A normalized telephone whose country
109	     * code appears here must carry exactly this many national digits after the code; Australia
110	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
111	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
112	     */
113	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
114	
115	    /**
116	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
117	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
118	     */
119	    private static final int MAX_OWNERS_PER_CITY = 50;
120	
121	    /**
122	     * Maximum number of owners that may be registered on a single day (by registration date). A create
123	     * attempted once this many owners already carry today's registration date is rejected with a
124	     * 429 Too Many Requests.
125	     */
126	    private static final int MAX_OWNERS_PER_DAY = 100;
127	
128	    /**
129	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
130	     * owners already carry the new owner's registration date, the created owner is flagged
131	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
132	     */
133	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
134	
135	    /**
136	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
137	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
138	     */
139	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
140	        "ST", "STREET",
141	        "RD", "ROAD",
142	        "AVE", "AVENUE");
143	
144	    /**
145	     * Inclusive 4-digit postcode range permitted per region, keyed by the region derived from the
146	     * owner's city ({@link Owner#getLocality()}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A
147	     * region not listed (the {@code 'UNKNOWN'} locality of a city with no known region) accepts any
148	     * 4-digit postcode.
149	     */
150	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
151	        "NSW", new int[] {2000, 2099},
152	        "VIC", new int[] {3000, 3099},
153	        "QLD", new int[] {4000, 4099});
154	
155	    public OwnerRestControllerV1(ClinicService clinicService,
156	                                 OwnerMapper ownerMapper,
157	                                 PetMapper petMapper,
158	                                 VisitMapper visitMapper) {
159	        this.clinicService = clinicService;
160	        this.ownerMapper = ownerMapper;
161	        this.petMapper = petMapper;
162	        this.visitMapper = visitMapper;
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
168	        Collection<Owner> owners;
169	        if (lastName != null) {
170	            owners = this.clinicService.findOwnerByLastName(lastName);
171	        } else {
172	            owners = this.clinicService.findAllOwners();
173	        }
174	        if (owners.isEmpty()) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
183	        Owner owner = this.clinicService.findOwnerById(ownerId);
184	        if (owner == null) {
185	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	        }
187	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
193	        validateRequiredFields(ownerFieldsDto);
194	        HttpHeaders headers = new HttpHeaders();
195	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
196	        rejectFutureRegistrationDate(owner.getRegistrationDate());
197	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
198	        owner.setRegistrationDate(registrationDate);
199	        requireDailyCapacity(registrationDate);
200	        requireCityHasCapacity(owner.getCity());
201	        validatePostcode(owner);
202	        applyAddress(owner, ownerFieldsDto);
203	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
204	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
205	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
206	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
207	        requireNoHouseholdDuplicate(owner, declaredHouseholdMember);
208	        requireUniqueIdentity(owner);
209	        flagPossibleDuplicate(owner, declaredHouseholdMember);
210	        owner.setCustomerCode(deduplicateCustomerCode(owner.buildCustomerCode()));
211	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
212	        stampHouseholdSize(owner);
213	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
214	        this.clinicService.saveOwner(owner);
215	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
216	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
217	            owner.getMembershipNumber());
218	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
219	        headers.setLocation(UriComponentsBuilder.newInstance()
220	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
221	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
222	    }
223	
224	    /**
225	     * Rejects a create whose supplied registration date is later than the server's current date. A
226	     * registration may be back-dated but never post-dated, so a future date is treated as a client
227	     * error. A {@code null} supplied date (the client omitted it) is allowed, as it defaults to the
228	     * server date.
229	     *
230	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when the
231	     *     client omitted it
232	     * @throws FutureRegistrationDateException if the supplied date is after the server's current date
233	     */
234	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
235	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
236	            throw new FutureRegistrationDateException(suppliedRegistrationDate);
237	        }
238	    }
239	
240	    /**
241	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
242	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
243	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
244	     * existed prior to this create.
245	     *
246	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
247	     *     a business day
248	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
249	     *     registered on that business day
250	     */
251	    private void requireDailyCapacity(LocalDate registrationDate) {
252	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
253	            throw new DailyOwnerLimitException(registrationDate);
254	        }
255	    }
256	
257	    /**
258	     * Counts the existing owners whose registration date equals the given business-day date. This is
259	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
260	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
261	     * the bulk-signup warning.
262	     *
263	     * @param registrationDate the effective business-day registration date to count against
264	     * @return the number of pre-existing owners registered on that date
265	     */
266	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
267	        return this.clinicService.findAllOwners().stream()
268	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
269	            .count();
270	    }
271	
272	    /**
273	     * Rejects an owner whose city already contains the maximum allowed number of owners
274	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
275	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
276	     * create.
277	     *
278	     * @param city the city of the owner being created
279	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
280	     */
281	    private void requireCityHasCapacity(String city) {
282	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
283	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
284	            .count();
285	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
286	            throw new CityOwnerLimitException(city);
287	        }
288	    }
289	
290	    /**
291	     * Validates a supplied postcode against the owner's region. Postcode is optional: an owner with no
292	     * postcode is accepted unchanged. When present it is a 4-digit string (enforced by the request
293	     * schema) that must fall within the inclusive range permitted for the region derived from the
294	     * owner's city ({@link #REGION_POSTCODE_RANGES}); a city whose region is unknown accepts any 4-digit
295	     * postcode. An out-of-range postcode is rejected with a 400 Bad Request.
296	     *
297	     * @param owner the owner being created, with its city and postcode set
298	     * @throws InvalidOwnerFieldsException if a supplied postcode is out of range for the city's region
299	     */
300	    private void validatePostcode(Owner owner) {
301	        String postcode = owner.getPostcode();
302	        if (postcode == null) {
303	            return;
304	        }
305	        int[] range = REGION_POSTCODE_RANGES.get(owner.getLocality());
306	        if (range == null) {
307	            return;
308	        }
309	        int value = Integer.parseInt(postcode);
310	        if (value < range[0] || value > range[1]) {
311	            throw new InvalidOwnerFieldsException(List.of("postcode"));
312	        }
313	    }
314	
315	    /**
316	     * Counts the existing owners that already share the given first name and last name, compared
317	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
318	     * owners that existed prior to this create.
319	     *
320	     * @param firstName the first name of the owner being created
321	     * @param lastName the last name of the owner being created
322	     * @return the number of pre-existing namesakes
323	     */
324	    private int countNamesakes(String firstName, String lastName) {
325	        return (int) this.clinicService.findAllOwners().stream()
326	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
327	                && equalsIgnoreCase(existing.getLastName(), lastName))
328	            .count();
329	    }
330	
331	    /**
332	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
333	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
334	     *
335	     * @param a the first value, possibly {@code null}
336	     * @param b the second value, possibly {@code null}
337	     * @return whether the values are equal ignoring case
338	     */
339	    private boolean equalsIgnoreCase(String a, String b) {
340	        return a == null ? b == null : a.equalsIgnoreCase(b);
341	    }
342	
343	    /**
344	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
345	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
346	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
347	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
348	     *
349	     * @param ownerFieldsDto the submitted owner fields
350	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
351	     */
352	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
353	        List<String> invalidFields = new ArrayList<>();
354	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
355	            invalidFields.add("firstName");
356	        }
357	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
358	            invalidFields.add("lastName");
359	        }
360	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddressLine1()))
361	            && !StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
362	            invalidFields.add("address");
363	        }
364	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
365	            invalidFields.add("city");
366	        }
367	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
368	            invalidFields.add("telephone");
369	        }
370	        if (!invalidFields.isEmpty()) {
371	            throw new InvalidOwnerFieldsException(invalidFields);
372	        }
373	    }
374	
375	    /**
376	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
377	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
378	     * what gets stored and returned.
379	     *
380	     * @param telephone the raw telephone value from the request
381	     * @return the normalized E.164 telephone number
382	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
383	     */
384	    private String normalizeTelephone(String telephone) {
385	        String e164 = toE164(telephone);
386	        if (e164 == null) {
387	            throw new InvalidOwnerFieldsException(List.of("telephone"));
388	        }
389	        return e164;
390	    }
391	
392	    /**
393	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
394	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
395	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
396	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
397	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
398	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
399	     *
400	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
401	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
402	     *
403	     * @param telephone the raw telephone value, possibly {@code null}
404	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
405	     */
406	    private String toE164(String telephone) {
407	        if (telephone == null) {
408	            return null;
409	        }
410	        String cleaned = telephone.replaceAll("[ \\-()]", "");
411	        String digits;
412	        if (cleaned.startsWith("+")) {
413	            digits = cleaned.substring(1);
414	        } else {
415	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
416	            digits = "61" + national;
417	        }
418	        if (!digits.matches("[0-9]{8,15}")) {
419	            return null;
420	        }
421	        if (!nationalNumberLengthValid(digits)) {
422	            return null;
423	        }
424	        return "+" + digits;
425	    }
426	
427	    /**
428	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
429	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
430	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
431	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
432	     * accepted, leaving only the generic total-length rule to apply.
433	     *
434	     * @param digits the E.164 digits without the leading {@code '+'}
435	     * @return {@code true} if the national-number length matches the country code's requirement
436	     */
437	    private boolean nationalNumberLengthValid(String digits) {
438	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
439	            String code = entry.getKey();
440	            if (digits.startsWith(code)) {
441	                return digits.length() - code.length() == entry.getValue();
442	            }
443	        }
444	        return true;
445	    }
446	
447	    /**
448	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
449	     * {@code null}. When present, the value must be a syntactically valid address whose domain is not
450	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); it is then stored and
451	     * returned lower-cased.
452	     *
453	     * @param email the raw email value from the request, possibly {@code null}
454	     * @return the lower-cased email, or {@code null} when none was supplied
455	     * @throws InvalidOwnerFieldsException if a value is present but is not a valid email address or
456	     *     its domain is on the disposable-domain blocklist
457	     */
458	    private String normalizeEmail(String email) {
459	        if (!StringUtils.hasText(email)) {
460	            return null;
461	        }
462	        String trimmed = email.trim();
463	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
464	            throw new InvalidOwnerFieldsException(List.of("email"));
465	        }
466	        String normalized = trimmed.toLowerCase(Locale.ROOT);
467	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
468	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
469	            throw new InvalidOwnerFieldsException(List.of("email"));
470	        }
471	        return normalized;
472	    }
473	
474	    /**
475	     * Rejects an owner whose whole identity key is already used by an existing owner. This is the
476	     * single consolidated duplicate check: the identity key ({@link Owner#getIdentityKey()}) is the
477	     * owner's normalized telephone, email (empty when absent) and household id joined with
478	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
479	     * owner's. Because the telephone is part of the key, two members of the same household
480	     * (same {@code householdId}) with different telephones have different identity keys and are both
481	     * allowed.
482	     *
483	     * @param owner the owner being created, with its normalized telephone, email and household id set
484	     * @throws DuplicateIdentityException if another owner already has this identity key
485	     */
486	    private void requireUniqueIdentity(Owner owner) {
487	        String identityKey = owner.getIdentityKey();
488	        boolean inUse = this.clinicService.findAllOwners().stream()
489	            .filter(existing -> !existing.isDeleted())
490	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
491	        if (inUse) {
492	            throw new DuplicateIdentityException(identityKey);
493	        }
494	    }
495	
496	    /**
497	     * De-duplicates a newly computed customer code against the codes already held by existing owners.
498	     * When the computed code is unique it is returned unchanged. When it collides with an existing
499	     * owner's {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more
500	     * that makes the result unique (so a second collision yields {@code '-2'}, a third {@code '-3'}, and
501	     * so on), and that de-duplicated code is returned.
502	     *
503	     * @param customerCode the freshly computed customer code to de-duplicate
504	     * @return a customer code not held by any existing owner
505	     */
506	    private String deduplicateCustomerCode(String customerCode) {
507	        Set<String> inUse = this.clinicService.findAllOwners().stream()
508	            .map(Owner::getCustomerCode)
509	            .filter(Objects::nonNull)
510	            .collect(Collectors.toSet());
511	        if (!inUse.contains(customerCode)) {
512	            return customerCode;
513	        }
514	        int n = 2;
515	        String candidate;
516	        do {
517	            candidate = customerCode + "-" + n;
518	            n++;
519	        } while (inUse.contains(candidate));
520	        return candidate;
521	    }
522	
523	    /**
524	     * Flags the owner being created as a possible (soft) duplicate of an existing owner. A soft match is
525	     * not a hard duplicate (its identity key is unique, already enforced by {@link #requireUniqueIdentity})
526	     * but it shares an existing owner's last name (compared case-insensitively) and postcode (both
527	     * present and equal) while carrying a different normalized telephone. When such an existing owner is
528	     * found the created owner is flagged ({@code possibleDuplicate} true) with {@code possibleDuplicateOf}
529	     * set to that owner's id; the lowest matching id is used when several owners match. Otherwise the flag
530	     * is false and {@code possibleDuplicateOf} is left unset.
531	     *
532	     * <p>A declared household member (one created with {@code sharesHousehold}) is never a suspected
533	     * duplicate: it has deliberately opted in to sharing its household, so the flag is forced false.
534	     *
535	     * @param owner the owner being created, with its normalized telephone and postcode set
536	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
537	     */
538	    private void flagPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
539	        if (declaredHouseholdMember || owner.getPostcode() == null) {
540	            owner.setPossibleDuplicate(false);
541	            return;
542	        }
543	        Integer matchId = this.clinicService.findAllOwners().stream()
544	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
545	                && owner.getPostcode().equals(existing.getPostcode())
546	                && !owner.getTelephone().equals(existing.getTelephone()))
547	            .map(Owner::getId)
548	            .min(Integer::compareTo)
549	            .orElse(null);
550	        owner.setPossibleDuplicate(matchId != null);
551	        owner.setPossibleDuplicateOf(matchId);
552	    }
553	
554	    /**
555	     * Rejects a create that would join an existing household unless it has opted in via
556	     * {@code sharesHousehold}. The household is keyed on the deterministic {@code householdId} (derived
557	     * from the normalized last name and postcode; see {@link #computeHouseholdId}), so any existing
558	     * owner carrying the same {@code householdId} is a member of the same household. When one exists and
559	     * the create has not declared household membership, the second owner is a household duplicate.
560	     *
561	     * <p>A create that declares {@code sharesHousehold} bypasses this block entirely and is created as a
562	     * declared household member.
563	     *
564	     * @param owner the owner being created, with its deterministic {@code householdId} already set
565	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
566	     * @throws DuplicateHouseholdException if an existing owner already shares the household and the
567	     *     create did not declare {@code sharesHousehold}
568	     */
569	    private void requireNoHouseholdDuplicate(Owner owner, boolean declaredHouseholdMember) {
570	        if (declaredHouseholdMember) {
571	            return;
572	        }
573	        String householdId = owner.getHouseholdId();
574	        boolean inUse = this.clinicService.findAllOwners().stream()
575	            .filter(existing -> !existing.isDeleted())
576	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
577	        if (inUse) {
578	            throw new DuplicateHouseholdException(householdId);
579	        }
580	    }
581	
582	    /**
583	     * Stamps the household's member count after this create ({@code householdSize}) onto every member of
584	     * the household - the existing owners that share the deterministic {@code householdId} and the new
585	     * one - so the shared size can be read back from any of them. The count is the number of existing
586	     * members plus the owner being created.
587	     *
588	     * @param owner the owner being created, with its deterministic {@code householdId} already set
589	     */
590	    private void stampHouseholdSize(Owner owner) {
591	        String householdId = owner.getHouseholdId();
592	        List<Owner> members = this.clinicService.findAllOwners().stream()
593	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
594	            .toList();
595	        int householdSize = members.size() + 1;
596	        owner.setHouseholdSize(householdSize);
597	        for (Owner member : members) {
598	            member.setHouseholdSize(householdSize);
599	            this.clinicService.saveOwner(member);
600	        }
601	    }
602	
603	    /**
604	     * Computes the deterministic, shared household identifier for a last name and postcode: the first
605	     * 12 upper-case hexadecimal characters (the first 6 bytes) of the SHA-256 digest of
606	     * {@code normalizedLastName + '|' + postcode}. The last name is normalized (case-insensitive,
607	     * whitespace-collapsed) and an absent postcode contributes an empty string, so every owner that
608	     * shares a last name and postcode computes the same identifier and therefore the same household.
609	     *
610	     * @param lastName the last name of the household
611	     * @param postcode the postcode of the household, possibly {@code null}
612	     * @return the 12-character upper-case hex household identifier
613	     */
614	    private String computeHouseholdId(String lastName, String postcode) {
615	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
616	        try {
617	            byte[] digest = MessageDigest.getInstance("SHA-256")
618	                .digest(key.getBytes(StandardCharsets.UTF_8));
619	            StringBuilder hex = new StringBuilder(12);
620	            for (int i = 0; i < 6; i++) {
621	                hex.append(String.format("%02X", digest[i]));
622	            }
623	            return hex.toString();
624	        } catch (NoSuchAlgorithmException e) {
625	            throw new IllegalStateException("SHA-256 algorithm not available", e);
626	        }
627	    }
628	
629	    /**
630	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
631	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
632	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
633	     *
634	     * @param value the raw value, possibly {@code null}
635	     * @return the normalized value
636	     */
637	    private String normalizeForHousehold(String value) {
638	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
639	    }
640	
641	    /**
642	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
643	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
644	     * value yields an empty string.
645	     *
646	     * @param value the raw value, possibly {@code null}
647	     * @return the trimmed, whitespace-collapsed value
648	     */
649	    private String collapseWhitespace(String value) {
650	        if (value == null) {
651	            return "";
652	        }
653	        return value.trim().replaceAll("\\s+", " ");
654	    }
655	
656	    /**
657	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
658	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
659	     * is upper-cased, and common street-type abbreviations are expanded as whole words
660	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
661	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
662	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
663	     *
664	     * @param address the raw address value, possibly {@code null}
665	     * @return the normalized address
666	     */
667	    private String normalizeAddress(String address) {
668	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
669	        if (collapsed.isEmpty()) {
670	            return "";
671	        }
672	        String[] tokens = collapsed.split(" ");
673	        StringBuilder normalized = new StringBuilder();
674	        for (int i = 0; i < tokens.length; i++) {
675	            if (i > 0) {
676	                normalized.append(' ');
677	            }
678	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
679	        }
680	        return normalized.toString();
681	    }
682	
683	    /**
684	     * Applies the owner's address from the request, preferring the structured form over the flat one.
685	     * When a non-blank {@code addressLine1} is supplied it is normalized ({@link #normalizeAddress}) and
686	     * stored, along with the normalized {@code addressLine2} when present, and the stored {@code address}
687	     * is the composed string ({@link #composeAddress}). Otherwise the flat {@code address} input is
688	     * normalized and stored, and the structured lines are cleared. Normalization therefore applies to
689	     * whichever address fields are supplied, and everything that reads {@link Owner#getAddress()} sees
690	     * the structured address when present, falling back to the flat address.
691	     *
692	     * @param owner the owner being created
693	     * @param ownerFieldsDto the submitted owner fields
694	     */
695	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
696	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
697	        if (StringUtils.hasText(line1)) {
698	            String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
699	            String normalizedLine2 = StringUtils.hasText(line2) ? line2 : null;
700	            owner.setAddressLine1(line1);
701	            owner.setAddressLine2(normalizedLine2);
702	            owner.setAddress(composeAddress(line1, normalizedLine2));
703	        } else {
704	            owner.setAddressLine1(null);
705	            owner.setAddressLine2(null);
706	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
707	        }
708	    }
709	
710	    /**
711	     * Composes the stored-and-returned {@code address} string from the normalized structured lines: the
712	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
713	     * appended when the second line is present.
714	     *
715	     * @param line1 the normalized first address line
716	     * @param line2 the normalized second address line, or {@code null} when absent
717	     * @return the composed address string
718	     */
719	    private String composeAddress(String line1, String line2) {
720	        return line2 == null ? line1 : line1 + " " + line2;
721	    }
722	
723	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
724	    @Override
725	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
726	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
727	        if (currentOwner == null) {
728	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
729	        }
730	        currentOwner.setAddress(ownerFieldsDto.getAddress());
731	        currentOwner.setCity(ownerFieldsDto.getCity());
732	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
733	        currentOwner.setLastName(ownerFieldsDto.getLastName());
734	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
735	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
736	        this.clinicService.saveOwner(currentOwner);
737	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
738	    }
739	
740	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
741	    @Transactional
742	    @Override
743	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
744	        Owner owner = this.clinicService.findOwnerById(ownerId);
745	        if (owner == null) {
746	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
747	        }
748	        owner.setDeleted(true);
749	        this.clinicService.saveOwner(owner);
750	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
751	    }
752	
753	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
754	    @Override
755	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
756	        Owner owner = this.clinicService.findOwnerById(ownerId);
757	        if (owner == null) {
758	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
759	        }
760	        HttpHeaders headers = new HttpHeaders();
761	        Pet pet = petMapper.toPet(petFieldsDto);
762	        owner.setId(ownerId);
763	        pet.setOwner(owner);
764	        pet.getType().setName(null);
765	        this.clinicService.savePet(pet);
766	        PetDto petDto = petMapper.toPetDto(pet);
767	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
768	            .buildAndExpand(pet.getId()).toUri());
769	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
770	    }
771	
772	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
773	    @Override
774	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
775	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
776	        if (currentOwner != null) {
777	            Pet currentPet = this.clinicService.findPetById(petId);
778	            if (currentPet != null) {
779	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
780	                currentPet.setName(petFieldsDto.getName());
781	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
782	                this.clinicService.savePet(currentPet);
783	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
784	            }
785	        }
786	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
787	    }
788	
789	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
790	    @Override
791	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
792	        HttpHeaders headers = new HttpHeaders();
793	        Visit visit = visitMapper.toVisit(visitFieldsDto);
794	        Pet pet = new Pet();
795	        pet.setId(petId);
796	        visit.setPet(pet);
797	        this.clinicService.saveVisit(visit);
798	        VisitDto visitDto = visitMapper.toVisitDto(visit);
799	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
800	            .buildAndExpand(visit.getId()).toUri());
801	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
802	    }
803	
804	
805	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
806	    @Override
807	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
808	        Owner owner = this.clinicService.findOwnerById(ownerId);
809	        if (owner != null) {
810	            Pet pet = owner.getPet(petId);
811	            if (pet != null) {
812	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
813	            }
814	        }
815	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
816	    }
817	}
